import{_ as s,o as a,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Debugging Cards","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/uix/debugging/cards.md","filePath":"en/projects/uix/debugging/cards.md","lastUpdated":1792852622000}'),t={name:"en/projects/uix/debugging/cards.md"};function l(r,e,h,o,p,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="debugging-cards" tabindex="-1">Debugging Cards <a class="header-anchor" href="#debugging-cards" aria-label="Permalink to &quot;Debugging Cards&quot;">​</a></h1><p>The DOM navigation can be tricky to get right the first few times, but you&#39;ll eventually get the hang of it.</p><p>To help you, you can use your browsers Element inspector to see which steps UIX takes.</p><ul><li>Open up the element inspector and find the base element (e.g. <code>#shadow-root</code> or card contained by <code>&lt;hui-card&gt;</code> or <code>&lt;ha-card&gt;</code> contained by a custom card or other element. See <a href="./../concepts/application">Concepts - application</a> for more details. This should contain a <code>&lt;uix-node&gt;</code> element whether you specified a style or not.</li><li>Make sure the <code>&lt;uix-node&gt;</code> element is selected.</li><li>Open up the browser&#39;s console (in chrome you can press Esc to open the console and inspector at the same time).</li><li>Type in <code>$0.uix_input</code> and press enter. <br> This is the style information that step of the chain was given. If this is a string, you&#39;re at the end of the chain. If it&#39;s an object, you can move on to the next step.</li><li>Type in <code>$0.uix_children</code> and press enter. <br> This is a set of any <code>&lt;uix-node&gt;</code> elements in the next step of any chain. Clicking &quot;uix&quot; in the <code>value:</code> of the set items will bring you to that <code>&lt;uix-node&gt;</code> element in the inspector, and you can keep on inspecting the rest of the chain.</li><li>You can also use <code>$0.uix_parent</code> to find the parent of any <code>&lt;uix-node&gt;</code> element in a chain.</li></ul><p>For a bit more information, you can use the following in the configuration of the card you&#39;re having problems with. It may or may not help you.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="setting-debug-via-theme-variables" tabindex="-1">Setting debug via theme variables <a class="header-anchor" href="#setting-debug-via-theme-variables" aria-label="Permalink to &quot;Setting debug via theme variables&quot;">​</a></h2><p>Just like you can set debug on a card with <code>uix:</code> -&gt; <code>debug: true</code>, you can also set debug via a theme variable. This may be the only way to debug a certain type and/or class when styling a panel that is not a Lovelace dashboard or a Lovelace strategy dashboard.</p><p>You can set debug via:</p><ol><li>Using the theme variable <code>uix-&lt;type&gt;-debug: true</code> (defined in your theme YAML file, without the leading <code>--</code>) to debug all elements of type <code>&lt;type&gt;</code>. In CSS, this variable is referenced as <code>--uix-&lt;type&gt;-debug</code>.</li><li>Using the theme variable <code>uix-&lt;type&gt;-&lt;class&gt;-debug: true</code> (again, without the leading <code>--</code> in YAML) to debug all elements of type <code>&lt;type&gt;</code> which have class <code>&lt;class&gt;</code>. In CSS, reference as <code>--uix-&lt;type&gt;-&lt;class&gt;-debug</code>. These include both classes that UIX sets as well as any class you included in UIX config for a card/element.</li></ol><p>Example:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">my-awesome-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-awesome-theme</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-card-debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Debug all elements of UIX type \`card\`</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">my-awesome-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-awesome-theme</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-card-type-energy-sankey-debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Debug card which has uix class &#39;type-energy-sankey&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-badge-my-class-debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Debug badges which have my-class set by uix config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">Set theme variables in Home Assistant theme</p><p>Theme debug variables are set in the Home Assistant theme which is in context, either global or applied locally via dashboard view or card (where supported). Theme debug variables are <strong>NOT</strong> read from <code>uix-theme</code> theme. So if these are different, make sure to set theme debug variables on the Home Assistant theme in context.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">theme-mods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ... UIX theme variables, styles, macros go here ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">my-awesome-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-card-type-energy-sankey-debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Debug card which has uix class &#39;type-energy-sankey&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-badge-my-class-debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Debug badges which have my-class set by uix config</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uix-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">theme-mods</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div></div>`,15)])])}const g=s(t,[["render",l]]);export{u as __pageData,g as default};
